import json
d=json.load(open('emc-fusion-partner-pooling.json'))
def walk(o,p='',depth=0):
    if depth>3: return
    if isinstance(o,dict):
        for k,v in o.items():
            print(' '*depth+p+'.'+k, type(v).__name__, (len(v) if isinstance(v,(list,dict)) else v) if not isinstance(v,str) else repr(v[:60]))
            walk(v,p+'.'+k,depth+1)
    elif isinstance(o,list):
        print(' '*depth+p+'[]',len(o))
        if o: walk(o[0],p+'[0]',depth+1)
walk(d)
